-- Academy skills catalogue + assessments, generated 2026-11-25. Idempotent: skills, competencies and assessments that already exist are left alone.
-- Level model: every assessment is a Professional-level (id 4) assessment. A score at or above the pass mark awards Professional;
-- 50% up to the pass mark awards the next lower level (Practitioner). Price is the existing Sales assessment price (TZS 10,000).
BEGIN;
DO $seed$
DECLARE v_skill int; v_assess int; v_sec_k int; v_sec_s int; v_q int; v_c int; v_comp jsonb := '{}'::jsonb;
BEGIN
  SELECT id INTO v_skill FROM academy.skills WHERE slug = 'teaching';
  IF v_skill IS NULL THEN RAISE EXCEPTION 'skill % not found', 'teaching'; END IF;
  IF EXISTS (SELECT 1 FROM academy.assessments WHERE skill_id = v_skill AND skill_level_id = 4) THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM academy.skill_competencies WHERE skill_id = v_skill) THEN RAISE EXCEPTION 'skill % already has competencies but no assessment: resolve by hand', 'teaching'; END IF;
  v_comp := v_comp || jsonb_build_object('Subject knowledge and teaching methods', v_c);
  v_comp := v_comp || jsonb_build_object('Lesson delivery and learner engagement', v_c);
  v_comp := v_comp || jsonb_build_object('Assessment and feedback', v_c);
  v_comp := v_comp || jsonb_build_object('Inclusion and meeting individual needs', v_c);
  v_comp := v_comp || jsonb_build_object('Child protection and professional conduct', v_c);
END $seed$;
