  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Positive behaviour and discipline')::int, 4, 'single', 'Two pupils begin pushing each other during a lesson. What should you do first?', 'medium', 8, 0, 'Safety comes first; a calm separation followed by private discussion addresses the cause and respects procedure.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Calmly separate them, then speak with each one later and follow school procedure', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Join in by shouting at both pupils in front of the whole class until they stop', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ignore it so the pupils learn to settle it themselves without the teacher''s help', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the other pupils to decide who is guilty and punish him in front of the class', 0, 0, '', 0, 4);
