  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Teach a re-entry routine: stand at the door, pupils enter quietly and begin a task on the board', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cancel the first ten minutes of each lesson after break', 0, 0, '', 0, 4);
