  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Positive behaviour and discipline')::int, 4, 'single', 'One pupil disturbs your lessons every day, and reminders have not worked. What is the best next step?', 'hard', 10, 0, 'Repeated misbehaviour usually has a cause; a private talk and agreed plan, with support, works better than exclusion or shaming.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Make him stand outside the classroom for the whole term so others can learn in peace', 0, 0, '', 0, 1);
