  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Child development')::int, 4, 'single', 'In a pre-primary class, some children speak in full sentences while others use only a few words. How should the teacher think about this?', 'medium', 8, 0, 'Children grow at different rates; teachers provide support and monitor progress without labelling.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Children develop at different rates, so she should support each child without comparing them', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The slower children are lazy and need to be punished', 0, 0, '', 0, 2);
