  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Bullying and abuse disclosures')::int, 4, 'single', 'A boy tells you that older boys bully him in the dormitory and begs you not to tell anyone. What should you do?', 'hard', 10, 0, 'Bullying must be addressed for the learner''s safety; be honest with him about the steps and report properly.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Confront the older boys publicly in the dining hall so that everyone sees the bullying stop', 0, 0, '', 0, 1);
