  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask them to memorise the whole passage so they can answer the questions from memory the next day', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Let them read the passage aloud many more times until they can remember most of the details', 0, 0, '', 0, 2);
