  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Writing')::int, 4, 'single', 'Which is the usual order of the stages in the writing process?', 'easy', 6, 0, 'Writers plan first, draft, revise ideas and organisation, then edit spelling and grammar, and finally publish or share.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Plan, edit, draft, publish, revise', 0, 0, '', 0, 1);
