  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Listening and Speaking')::int, 4, 'single', 'Several shy pupils never speak English in class. What is the best strategy?', 'medium', 8, 0, 'Low-pressure pair and group work builds confidence and gives every pupil more speaking practice.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Let only the confident pupils answer so that lessons move faster and no time is wasted', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Start with pair or small-group speaking tasks before asking for answers in front of everyone', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Call on them first so they get used to speaking in front of everyone in the class', 0, 0, '', 0, 3);
