  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the pupil the answer is wrong and move on to the next topic without any demonstration', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree, because heavier objects feel a stronger pull of gravity and so must always fall faster to the ground than light ones', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the pupil to copy the definition of gravity into the notebook and learn it by heart for the next test on Friday', 0, 0, '', 0, 3);
