  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Rub the area with a dry cloth and let her continue the practical so she does not miss it', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Do nothing at all if the pupil says there is no pain and the skin looks normal', 0, 0, '', 0, 2);
