  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Demonstrate with local materials such as water, ice and bottles and let pupils record observations', 1, 0, '', 0, 1);
