  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Reconciliations and internal controls')::int, 4, 'single', 'A trial balance agrees (debits equal credits). Which error would still NOT be revealed by it?', 'hard', 10, 0, 'Posting to the wrong account of the right type keeps debits equal to credits. The other errors make the two totals different.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A debit entry posted but the matching credit left out of the ledger completely', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A debit of TZS 45,000 posted as TZS 54,000 only', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A purchase of stationery posted to the repairs expense account', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A credit entry posted twice with one debit', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Reconciliations and internal controls')::int, 4, 'single', 'While preparing a bank reconciliation you find a TZS 800,000 withdrawal on the bank statement that is not in the cash book and nobody can explain it. What should you do?', 'medium', 8, 0, 'Unexplained bank items may be errors or fraud. They must be reported and investigated, not hidden in an expense account.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Report it to the accountant or head and ask the bank for the supporting document', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Record it as a miscellaneous expense so the books balance and the reconciliation closes', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Leave it in the reconciliation until the year-end audit', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the cashier to correct the cash book without telling anyone', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Double-entry and journals')::int, 4, 'single', 'The school buys 5 desks for TZS 750,000 and the supplier gives 30 days to pay. The invoice is not yet paid. Which entry is correct?', 'easy', 6, 0, 'The desks are an asset, and the school now owes the supplier, so a liability (creditors) is created instead of reducing cash.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Debit Furniture, credit Cash', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Debit Furniture, credit Creditors (accounts payable)', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Debit Furniture expense, credit Fee income for the term', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Debit Creditors, credit Furniture', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Accounting practice and ethics')::int, 4, 'single', 'Last month''s books are closed. A manager asks you to change the date of a TZS 2,000,000 expense so that it appears in last month and next month looks better. What is the best response?', 'hard', 10, 0, 'Records must show when transactions really happened. Changing dates to influence results is misreporting, so it should be declined and escalated.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree, because the manager is responsible for the results of the school', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree if it is only a small amount for the school', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Change the date and add a note in your own file', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Decline, record it with its true date and tell your supervisor', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Financial statements')::int, 4, 'single', 'A board member notes that the income statement shows a surplus of TZS 3,000,000, but the bank balance is very low. What is the most likely explanation?', 'medium', 8, 0, 'A surplus is income earned minus expenses incurred. Unpaid fees and cash spent on assets reduce cash without reducing the surplus.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Some fees are invoiced but not yet collected, and cash was used to buy equipment', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The surplus must always equal the bank balance, so a mistake was made in the accounts', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The bank has made an error and should be contacted', 0, 0, '', 0, 3);
