  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Accounting practice and ethics')::int, 4, 'single', 'The petty cash float is TZS 100,000 under the imprest system. Paid vouchers total TZS 62,000 and the box holds TZS 38,000. What should be done to restore the float?', 'medium', 8, 0, 'Under an imprest system the cash plus vouchers always equals the float, and the vouchers total is refunded to restore it.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Do nothing, because the cash left in the box is already the correct amount', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reimburse TZS 38,000 and keep the vouchers for later', 0, 0, '', 0, 2);
