  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Ledgers and double entry')::int, 4, 'single', 'You posted the school''s electricity bill to the Water expense account by mistake. What is the best way to correct it?', 'medium', 8, 0, 'Records must keep an audit trail, so errors are corrected by a journal (debit Electricity, credit Water) and not by erasing.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Erase the original entry and write it again in the correct account', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Delete the page and re-create it without a note', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Leave it until the auditors find it', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Make a correcting journal entry with a clear explanation', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Trial balance and error finding')::int, 4, 'single', 'Your trial balance does not agree, and you have already re-added the columns. What is the best next step?', 'hard', 10, 0, 'A difference equal to one entry suggests an omission, and half of an entry suggests a debit/credit reversed. A suspense account is only a temporary place to hold a difference until it is found.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Check if the difference equals one entry or half of one, then trace postings', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Put the difference in a suspense account and treat the trial balance as agreed', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Adjust the cash balance by the difference so that the totals agree', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Start the entire year''s books again from January and ignore the old ones', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Bank reconciliation')::int, 4, 'single', 'The cash book balance is TZS 2,400,000. The bank statement shows TZS 2,560,000. Unpresented cheques are TZS 300,000. The only other difference is an uncredited deposit. How much is that deposit?', 'hard', 10, 0, 'Bank balance 2,560,000 - cheques 300,000 + deposit = cash book 2,400,000, so the deposit is 140,000.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 160,000', 0, 0, '', 0, 1);
