  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Statutory deductions and contributions')::int, 4, 'multiple', 'Which of these are costs paid by the employer and NOT deducted from the employee''s salary? Select all that apply.', 'medium', 8, 0, 'WCF and SDL are employer obligations. PAYE, the employee''s pension share and HESLB loan repayments are deducted from the employee''s pay.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Workers Compensation Fund (WCF) contribution', 1, 0, '', 0, 1);
