  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Gross-to-net pay and payslips')::int, 4, 'single', 'How is an employee''s net pay calculated?', 'easy', 6, 0, 'Net pay is the amount the employee receives after PAYE, the employee pension share and other authorised deductions are taken from gross pay.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Basic salary plus all allowances paid to the employee in the month', 0, 0, '', 0, 1);
