  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Gross pay minus all deductions taken from the employee', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Statutory deductions and contributions')::int, 4, 'single', 'Which authority collects PAYE from employers in Tanzania?', 'easy', 6, 0, 'PAYE is income tax, and employers withhold it and pay it to the TRA.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tanzania Revenue Authority (TRA)', 1, 0, '', 0, 1);
