  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The local government authority', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Statutory deductions and contributions')::int, 4, 'single', 'Which fund is the social security scheme for public servants, such as teachers employed by the government?', 'easy', 6, 0, 'PSSSF covers public servants, while NSSF mainly covers private-sector employees.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Workers Compensation Fund (WCF)', 0, 0, '', 0, 1);
