  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Budget preparation')::int, 4, 'multiple', 'Which information is needed to estimate next year''s fee income? Select all that apply.', 'easy', 6, 0, 'Fee income depends on pupil numbers, fee levels and how much will actually be collected. Salaries and repairs are expenses.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The approved fee per pupil', 1, 0, '', 0, 1);
