  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Variance analysis')::int, 4, 'single', 'The electricity budget for the month is TZS 600,000 and the actual cost is TZS 540,000. What is the variance?', 'easy', 6, 0, 'Spending below budget is a favourable variance: 600,000 - 540,000 = 60,000.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 60,000 favourable', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 60,000 adverse', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 540,000 favourable', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 600,000 adverse', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Variance analysis')::int, 4, 'single', 'Budgeted fee income for the term was TZS 20,000,000. Actual fee income was TZS 17,000,000. What is the variance as a percentage of budget?', 'medium', 8, 0, 'The shortfall is 3,000,000, which is 15% of 20,000,000. Income lower than budget is adverse.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '15% favourable', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '17% adverse', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '15% adverse', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '3% adverse', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Cash-flow forecasting')::int, 4, 'single', 'Why can a school with a budget surplus still run out of cash?', 'medium', 8, 0, 'A budget shows totals, but a cash-flow forecast shows timing. Late collections and early payments can cause a cash shortage.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A surplus budget always creates the same amount of cash in the bank automatically', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cash problems only happen when the budget has a deficit', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The bank takes the surplus at the end of each term', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Fees may be collected late while expenses must be paid every month', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Cash-flow forecasting')::int, 4, 'multiple', 'Which items belong in a monthly cash-flow forecast? Select all that apply.', 'medium', 8, 0, 'Cash-flow forecasts include actual cash movements. Depreciation and allowances are non-cash accounting entries.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Depreciation of school vehicles', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A bank loan instalment due in the month', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The allowance for doubtful debts', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Fees expected to be collected in the month', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Salaries paid at month-end', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Budget preparation')::int, 4, 'single', 'Which best describes zero-based budgeting?', 'hard', 10, 0, 'In zero-based budgeting nothing is assumed from last year, so each cost must be justified and approved afresh.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Last year''s budget is carried forward and increased by a fixed percentage each year', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Planned income is set exactly equal to planned spending', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Each budget line must be justified again every period, starting from zero', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The budget is changed every month to match actual results', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Variance analysis')::int, 4, 'single', 'Halfway through the year, maintenance spending is 40% above budget because a storm damaged the roof. What is the best action?', 'medium', 8, 0, 'Variances should be explained and reported, with an approved decision on how to fund them. Records must never be changed to hide a variance.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Investigate, report the cause to management and ask for approved reallocation or extra funds', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ignore it, because it is a one-off event', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Stop all maintenance until the new financial year starts, including urgent safety repairs', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reduce the recorded expense so that it matches the budget and the variance disappears from reports', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Budget monitoring and control')::int, 4, 'single', 'A department asks you to buy equipment costing TZS 2,000,000 that is not in the approved budget. What should you do?', 'easy', 6, 0, 'Unbudgeted spending is possible, but only through the proper approval process and with a funding source identified.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Buy it now and move the cost to another budget line once the month is closed', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the requester to submit it for approval through the unbudgeted-expense procedure', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Refuse every unbudgeted request under all circumstances, including urgent safety needs', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Approve it directly, because the head of department has asked for it in writing', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Cash-flow forecasting')::int, 4, 'single', 'Your forecast shows a cash shortfall in two months because most fees arrive later. What is the best approach?', 'hard', 10, 0, 'A forecast lets you act before the shortfall. Money collected for a specific purpose, such as exams, should not be spent on other items.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until the shortfall actually happens, then ask the bank for an overdraft quickly', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use the exam fees already collected from parents to pay general expenses until fees arrive', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reduce staff salaries without telling them', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Plan early: follow up arrears, negotiate supplier terms and delay non-essential spending', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Prioritisation and planning')::int, 4, 'single', 'Budget requests total TZS 30 million, but only TZS 22 million is available. How should the requests be handled?', 'medium', 8, 0, 'Limited funds should go first to essential, high-priority needs agreed with stakeholders, not to equal cuts or first-come requests.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Rank them by priority and fund essential items first, such as safety and salaries', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cut every request by the same percentage so that each department is treated equally', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Fund requests in the order in which they were received until the money is finished', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Fund the requests from the most senior staff first, then the others if money remains', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Budget monitoring and control')::int, 4, 'single', 'The stationery budget is TZS 5,000,000. Spent so far: TZS 3,000,000. Approved orders not yet delivered: TZS 1,500,000. A new order of TZS 800,000 is requested. What is the correct conclusion?', 'hard', 10, 0, 'Available budget = 5,000,000 - 3,000,000 spent - 1,500,000 committed = 500,000. The 800,000 order exceeds it.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 2,000,000 is available, so the order can go ahead', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'TZS 3,500,000 is available, so the order can go ahead', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only TZS 500,000 is available, so the order needs extra approval', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The order can go ahead, since only the money actually spent counts against the budget', 0, 0, '', 0, 4);
