  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Mobile money and bank reconciliation')::int, 4, 'single', 'Why should a bank deposit slip shown by a parent be confirmed on the bank statement before the account is marked as paid?', 'medium', 8, 0, 'A slip is not proof that the money reached the school''s account. Only the bank statement confirms receipt.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The bank statement is printed more clearly than slips and is easier to keep in files', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The slip only shows the date and not the amount', 0, 0, '', 0, 2);
