  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Parents are not allowed to make bank deposits for fees', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Mobile money and bank reconciliation')::int, 4, 'multiple', 'Which details help match a mobile money payment to the right pupil? Select all that apply.', 'medium', 8, 0, 'Unique references and payment details link a payment to an account. Personal details unrelated to the payment do not help matching.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The pupil''s admission or control number used as reference', 1, 0, '', 0, 1);
