  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Arrears follow-up and payment plans')::int, 4, 'single', 'A family has left the country. After reasonable follow-up, TZS 1,200,000 of fees cannot be recovered. What is the correct treatment?', 'hard', 10, 0, 'Bad debts are written off only with documented approval, so the record stays visible and the process can be checked.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Delete the pupil''s balance from the system quietly so that the debtors list looks clean', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Move the amount to another pupil''s account', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Write it off with written approval from the authorised person and keep the record', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Keep it on the current-term list forever', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Fraud awareness and controls')::int, 4, 'single', 'A parent says she gave TZS 400,000 cash to the class teacher but has no receipt, and the school has not received it. What should you do?', 'easy', 6, 0, 'Fees should be paid only to the cashier or official accounts with an official receipt. Check the facts before changing records.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Do not mark it paid; check with the teacher and remind parents of official channels', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Mark it as paid, because the parent is a trusted and long-standing member of the school', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the parent that the loss is her own problem and that nothing can be done', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the teacher to give you cash from his own pocket to cover the amount', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Mobile money and bank reconciliation')::int, 4, 'single', 'A mobile money payment of TZS 450,000 has the reference "Hassan". Two pupils named Hassan are in the school. What is the best action?', 'medium', 8, 0, 'Never guess allocations. Confirm with the payer, and keep the money unallocated until it is identified.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Allocate it to the Hassan who has the larger unpaid balance, since he owes the most money', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Hold it as unallocated, contact the payer on the number shown and confirm which pupil', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Split it equally between both pupils', 0, 0, '', 0, 3);
