  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Fraud awareness and controls')::int, 4, 'single', 'A parent says he paid TZS 800,000 to a number given by someone on WhatsApp who claimed to be the school accountant. What is the best action?', 'hard', 10, 0, 'This is probably a scam. The school should confirm and report it, warn other parents and never credit money it did not receive.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Credit the pupil''s account in full, because the parent acted honestly and in good faith in the matter', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the parent to pay again and keep the receipt of the first', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ignore it, since the money did not come to the school', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Check the number is not official, report to the head, and tell parents the official channels', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Parent communication')::int, 4, 'single', 'A parent who recently lost her job comes upset about an arrears notice, and she raises her voice in a busy office. What should you do?', 'medium', 8, 0, 'Calm, private and respectful communication protects dignity and usually leads to a written payment plan under school policy.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Invite her to a private place, check her balance and explain the payment options', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask her to leave the office now and to come back only when she has the money', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell her loudly that rules apply to everyone', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Remove her child''s name from the class list until the full arrears have been paid', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Mobile money and bank reconciliation')::int, 4, 'single', 'At month-end, fee receipts issued total TZS 12,500,000, but bank and mobile money credits for fees total TZS 12,200,000. What is the best action?', 'hard', 10, 0, 'A difference means some receipts may not have been banked or some credits are unrecorded. Item-by-item matching finds the cause.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reduce the receipts total by TZS 300,000 so that the two totals will agree again at month-end', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until the end of the year to check the difference', 0, 0, '', 0, 2);
