  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Purchasing procedures and approvals')::int, 4, 'single', 'The head asks you to buy three laptops for TZS 4,500,000 from his relative without quotations. What is the best response?', 'hard', 10, 0, 'Procurement must be fair and transparent. Conflicts of interest must be declared, and splitting orders or fake quotations breaks the rules.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Insist on quotations, declare the conflict of interest and follow approval rules', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Buy them as asked, since the head has the final authority over all school spending', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Split the order into three smaller orders so that each stays below the approval limit', 0, 0, '', 0, 3);
