  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Receiving and inspecting goods')::int, 4, 'single', 'A delivery note shows 50 bags of rice, but three bags are torn when delivered. What should you do?', 'medium', 8, 0, 'Goods are accepted only after checking quantity and condition. Damage must be recorded on the delivery documents for a replacement or credit.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
