  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Office Operations & Supplies')::int, 4, 'single', 'You buy printer toner using petty cash, but the shop gives no receipt. What should you do?', 'hard', 10, 0, 'Every petty cash payment needs supporting evidence so that the spending can be checked later.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
