  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Confidentiality & Professional Conduct')::int, 4, 'single', 'A caller says he is from a government office and asks for a colleague''s home address and salary. You cannot confirm who he is. What do you do?', 'hard', 10, 0, 'Personal details must not be given to unverified callers; the request should go to someone authorised to decide.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
