  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Lend it for one night only, because he promises to return it first thing the next morning before lessons', 0, 0, '', 0, 1);
