  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Programming Fundamentals')::int, 4, 'single', 'In JavaScript, what is printed by this code?  let x = 5; x = x + 2; x = x * 3; console.log(x);', 'medium', 8, 0, 'x becomes 7 after the addition, then 7 * 3 = 21.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
