  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Hardware & Peripherals')::int, 4, 'single', 'Which part of a computer holds the data and programs currently in use, and loses them when power is switched off?', 'easy', 6, 0, 'RAM is temporary working memory. Its contents are lost when the computer is switched off.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
