  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'SQL Queries & Filtering')::int, 4, 'single', 'The students table has a phone column. What does this query return?  SELECT COUNT(*) FROM students WHERE phone = NULL;', 'hard', 10, 0, 'NULL means unknown, so phone = NULL is never true. Use phone IS NULL to find missing values.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
