  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'SQL Queries & Filtering')::int, 4, 'single', 'You must correct the amount of one payment (id 57) on the live database. What is the safest way?', 'medium', 8, 0, 'Previewing the row with SELECT and using a WHERE clause (with a backup) prevents changing or losing other rows.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Run UPDATE payments SET amount = 50000; on the whole table and fix the other rows later', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'First SELECT with WHERE id = 57, then UPDATE with the same WHERE, after a backup', 1, 0, '', 0, 2);
