  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'SELECT s.name, p.amount FROM students s INNER JOIN payments p ON p.student_id = s.id;', 0, 0, '', 0, 1);
