  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Joins & Aggregation')::int, 4, 'single', 'What does this query return?  SELECT class_id, COUNT(*) FROM students GROUP BY class_id;', 'easy', 6, 0, 'GROUP BY makes one group per class_id, and COUNT(*) counts the rows in each group.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
