  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Indexes & Performance')::int, 4, 'single', 'What is the main trade-off of adding an index to a column?', 'medium', 8, 0, 'An index speeds up reads on that column, but the database must maintain it on every write and store it.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'It makes inserts faster but searches slower, because the data is stored twice', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'It removes duplicate values from the column automatically, and this cannot be undone', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'It makes searches on the column faster but uses more storage and slows inserts', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'It encrypts the column but needs a password for every query that uses it', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Indexes & Performance')::int, 4, 'single', 'The query SELECT * FROM payments WHERE student_id = 120 is slow on a table with 2 million rows, and student_id has no index. What is the best action?', 'hard', 10, 0, 'An index on the column used in the WHERE clause lets the database find rows without scanning the whole table.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
