  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Integrity, Backup & Security')::int, 4, 'multiple', 'Select all that apply: which features help keep the data in a database accurate?', 'medium', 8, 0, 'Foreign keys, NOT NULL and UNIQUE constraints stop invalid or duplicate data. The other two practices weaken data quality and security.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
