  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Triage & Prioritisation')::int, 4, 'multiple', 'Select all that apply: which facts help you decide the priority of a support ticket?', 'medium', 8, 0, 'Impact, workaround and deadlines decide priority. Message length and politeness do not change how serious the problem is.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
