  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Formulas and functions')::int, 4, 'single', 'Cells A2:A5 contain Paid, Unpaid, Paid, Paid. Cells B2:B5 contain 50000, 30000, 20000, 10000. What does =SUMIF(A2:A5,"Paid",B2:B5) return?', 'medium', 8, 0, 'SUMIF adds only the values in B where column A says Paid: 50000 + 20000 + 10000 = 80000.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '110000', 0, 0, '', 0, 1);
