  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Formulas and functions')::int, 4, 'single', 'Admission numbers are in column A, names in B and fee balances in C (rows 2 to 100). You type an admission number in F2. Which formula returns that student''s fee balance using an exact match?', 'medium', 8, 0, 'VLOOKUP with the last argument FALSE finds an exact match and column index 3 returns the balance in column C.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '=VLOOKUP(F2,A2:C100,3,FALSE)', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '=VLOOKUP(F2,$A$2:$C$100,3,TRUE)', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '=HLOOKUP(F2,A2:C100,3,FALSE)', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '=VLOOKUP(F2,A2:C100,4,FALSE)', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Formulas and functions')::int, 4, 'single', 'In D2 you type =B2*C1, where C1 holds a commission rate. When you copy the formula down, D3 gives a wrong answer. Which formula in D2, copied down, will use C1 correctly in every row?', 'hard', 10, 0, 'Dollar signs make C1 an absolute reference, so it does not move when the formula is copied down.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '=ROUND($B2*C1,0)', 0, 0, '', 0, 1);
