  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Data cleaning')::int, 4, 'single', 'You import fee amounts from the school system. The total from SUM is lower than expected, and some amounts are left-aligned with a small green triangle. What is the most likely cause?', 'medium', 8, 0, 'Numbers stored as text are ignored by SUM. Convert them to real numbers.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The worksheet has already run out of empty rows', 0, 0, '', 0, 1);
