  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'KPIs and metrics')::int, 4, 'single', 'A school wants to improve fee collection. Which is the best KPI to track?', 'medium', 8, 0, 'A KPI should measure the outcome you want. The share of invoiced fees collected shows real progress. Reminders sent only measure activity.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
