  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Percentage of invoiced fees collected by the end of term', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Number of staff working in the accounts office at the school', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'KPIs and metrics')::int, 4, 'multiple', 'A school owner asks for a dashboard of what matters. Which of these are clearly defined KPIs? Select all that apply.', 'hard', 10, 0, 'Good KPIs have a clear formula. Attendance rate, collection rate and student-teacher ratio are all measurable. "Overall school quality" and "number of charts" are not defined measures.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Overall school quality, as people feel it', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Attendance rate = days present divided by total school days', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Fee collection rate = fees paid divided by fees invoiced', 1, 0, '', 0, 3);
