  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A print-ready PDF with sharp images, CMYK colour and bleed', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A low-resolution PowerPoint file saved in RGB colours', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Preparing print and social media assets')::int, 4, 'single', 'You must use one design for an Instagram post and a Facebook cover photo. What is the best approach?', 'medium', 8, 0, 'Each platform has its own recommended sizes. Resize or crop each version and keep important text in the safe area, away from the edges.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Resize for each platform and keep key text away from the edges', 1, 0, '', 0, 1);
