  INSERT INTO academy.assessments (skill_id, skill_level_id, title, description, duration_minutes, pass_score, critical_min, total_questions, max_attempts, cooldown_days, version, status, created_at, updated_at) VALUES (v_skill, 4, 'Customer Service — Professional', 'Checks whether the candidate can handle customers professionally and effectively by phone, WhatsApp and in person.', 30, 70, 60, 12, 1, 7, 1, 'published', now(), now()) RETURNING id INTO v_assess;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Knowledge', 'knowledge', 7, 1) RETURNING id INTO v_sec_k;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Situational Judgment', 'situational', 5, 2) RETURNING id INTO v_sec_s;
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Communication Channels and Etiquette')::int, 4, 'single', 'A customer calls your school-software support line. What is the best way to begin the call?', 'easy', 6, 0, 'A clear greeting with your name and company is polite and builds trust. Then you ask how you can help.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Say ''Hello'' and then wait silently until the customer has explained everything.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Greet the customer, say your name and company, and ask how you can help.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the customer to send the problem by email instead of speaking to you.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask for the customer''s account number before you say anything else.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Communication Channels and Etiquette')::int, 4, 'single', 'A parent sends a WhatsApp message at 8 pm asking about a fee balance. Your office closes at 5 pm. What is the best response?', 'medium', 8, 0, 'A short acknowledgement with a clear time for the answer manages expectations. Guessing a balance or disturbing the parent at night is unprofessional.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until Friday so that you can answer all of the week''s fee messages together in one batch.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Guess the balance from last term''s figures so that the parent is not left waiting overnight.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reply briefly that you received the message and will give the balance tomorrow morning.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Phone the parent repeatedly during the night until the parent answers to give the balance.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Empathy and Active Listening')::int, 4, 'single', 'What does active listening mean?', 'easy', 6, 0, 'Active listening means focusing on the speaker, letting them finish, and confirming what you heard.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Thinking about your reply while the customer is still speaking, so that you answer faster.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Repeating the same sentence louder and more slowly until the customer finally agrees.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Writing down only the customer''s name and phone number so that you can call back later.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Giving full attention, not interrupting, and checking that you understood.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Empathy and Active Listening')::int, 4, 'single', 'A parent comes to the school office and shouts that the invoice is wrong. What should you do first?', 'medium', 8, 0, 'Letting the person speak and acknowledging the concern calms the situation. You then check the facts before taking any action.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Let the parent finish, show that you understand the concern, then check the invoice.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the parent that the office never makes mistakes and that the invoice must be paid as shown.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cancel the invoice immediately and issue a new one so that the parent calms down quickly.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the parent to leave and come back later with another family member to discuss it calmly.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Problem Solving and Ownership')::int, 4, 'single', 'You cannot solve a customer''s problem and must pass it to a colleague. What is the best practice?', 'medium', 8, 0, 'A good hand-over means the customer does not repeat the story and knows who will help and when.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the customer it is not your department and that they should call the main office again tomorrow.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Pass on only the customer''s name and phone number and let the colleague ask everything again.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Explain who will help, share all case details, and say when the customer will hear back.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Promise that the problem will be fixed today without first checking with the colleague who will handle it.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Problem Solving and Ownership')::int, 4, 'single', 'A school bursar says a parent paid by mobile money, but the system shows no payment. What is the best first action?', 'hard', 10, 0, 'Verify the details first. Asking for double payment, denying the payment, or recording it without checking can all cause loss or disputes.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the parent to pay again so that the system can update, and promise to refund the first payment later.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask for the transaction reference, amount and time, then check them against the payment records.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Say that the payment never happened because it is not in the system, and ask the parent to bring proof.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Record the payment as received without checking, to keep the parent happy and avoid a long argument.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Handling Complaints and Difficult Customers')::int, 4, 'multiple', 'Which actions help to calm an angry customer? Select all that apply.', 'medium', 8, 0, 'A calm tone, a sincere apology with next steps, and patient listening reduce anger. Telling someone to calm down or blaming them makes it worse.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the customer to calm down.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Speak slowly and calmly in a respectful tone.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Point out immediately where the customer made a mistake.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Apologise for the inconvenience and explain what you will do next.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Listen without interrupting until the customer has finished.', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Handling Complaints and Difficult Customers')::int, 4, 'single', 'A school owner asks you to waive a setup fee, but company policy does not allow it. What is the best response?', 'hard', 10, 0, 'Explaining the policy respectfully, offering alternatives and escalating when asked is honest and keeps the relationship. Over-promising or ignoring policy causes bigger problems later.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree quietly now, and then ask your manager to approve the waiver later when nobody is watching the accounts.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Say you will ask your manager and promise the owner that the waiver will be approved by the end of the week.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Refuse and end the call straight away because the policy is final and cannot be discussed with anyone.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Explain the policy and its reason politely, offer what is allowed, and escalate if the owner asks.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Problem Solving and Ownership')::int, 4, 'single', 'The same problem is reported by several schools every week. What is the best long-term action?', 'hard', 10, 0, 'Repeated problems need a root-cause fix. Closing each case with a workaround treats the symptom, not the cause.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Find the root cause, record the pattern, and report it so that it can be fixed.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give each school the same temporary workaround and keep closing the cases.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the schools that the problem is known and they must wait.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Handle it only when a school complains loudly enough.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Follow-up and Service Standards')::int, 4, 'single', 'Why should you follow up with a customer after solving their problem?', 'easy', 6, 0, 'Follow-up confirms the solution worked and shows the customer that you care about the result.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'To make the customer buy another product immediately.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'To confirm that the problem is really solved and the customer is satisfied.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'To keep the ticket open for longer on the system.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'To avoid receiving more calls from the same customer.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Communication Channels and Etiquette')::int, 4, 'multiple', 'Which are good practices when giving support by WhatsApp? Select all that apply.', 'medium', 8, 0, 'Short clear messages, protecting other customers'' privacy and confirming understanding make WhatsApp support professional.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Keep messages short, clear and polite.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use slang and many abbreviations to sound friendly.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Do not share another customer''s personal details.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reply ''OK'' when you did not understand the request.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Confirm that you understood the problem before giving a solution.', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Follow-up and Service Standards')::int, 4, 'single', 'You promised a school to call back on Friday, but you still do not have the answer. What should you do?', 'hard', 10, 0, 'Keeping your promise to update, even without the final answer, protects trust and lets the customer plan.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until you have the answer, even if it takes until next week.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask a colleague to say that you are not available.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Call on Friday as promised, explain the progress, and agree on a new time.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Send the answer later without any message on Friday.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_products (skill_id, skill_level_id, assessment_id, price, currency, active, created_at) VALUES (v_skill, 4, v_assess, 10000, 'TZS', 1, now());
