  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 60);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Training and Adoption', 'Training users by role and helping them to use the software regularly.', 20, 0, 2, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Customer Health Monitoring', 'Using usage and relationship signals to see which customers are healthy or at risk.', 20, 0, 3, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Retention and Churn Prevention', 'Acting early to keep customers, understanding reasons for leaving and handling renewals fairly.', 25, 1, 4, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 60);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Stakeholder Communication', 'Setting expectations and giving clear updates to school leaders and users.', 10, 0, 5, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.assessments (skill_id, skill_level_id, title, description, duration_minutes, pass_score, critical_min, total_questions, max_attempts, cooldown_days, version, status, created_at, updated_at) VALUES (v_skill, 4, 'Customer Success & Onboarding — Professional', 'Checks whether the candidate can onboard schools onto software, drive adoption, monitor account health and prevent churn.', 30, 70, 60, 12, 1, 7, 1, 'published', now(), now()) RETURNING id INTO v_assess;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Knowledge', 'knowledge', 7, 1) RETURNING id INTO v_sec_k;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Situational Judgment', 'situational', 5, 2) RETURNING id INTO v_sec_s;
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Onboarding Planning')::int, 4, 'single', 'What is the main goal of onboarding a new school onto school-management software?', 'easy', 6, 0, 'Onboarding exists to bring the customer to real value quickly. Payment, long demos and zero support are not the goal.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Collect the first payment as quickly as possible, before the school changes its mind.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Show every feature of the system in one long meeting so that nothing is left out.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Help the school use the key features correctly so that it gets value quickly.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Make sure the school never needs to contact support after the go-live date has passed.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Onboarding Planning')::int, 4, 'single', 'Which activity should happen early in onboarding, before the main training?', 'medium', 8, 0, 'A shared plan with goals, dates and owners keeps onboarding on track from the start.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree the school''s goals, a timeline, and who is responsible for each task.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Send an invoice for next year''s renewal so that the payment is arranged in advance.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Switch on all optional features for every user so that nobody misses anything later.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until staff ask for training before planning anything, so the sessions match their needs.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Onboarding Planning')::int, 4, 'single', 'A school has 800 student records in several Excel files with different formats and wants to go live next week. What is the best approach?', 'medium', 8, 0, 'Clean, checked data is the base of a successful start. A short delay is better than wrong records for the whole term.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Import all files as they are to meet the go-live date, and correct any errors during the term.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree a standard template, clean and check the data, import it, and move the date if needed.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the school that the software cannot work with Excel files and that it must retype everything.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Type all 800 students yourself from the files, without checking them against the original records.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Training and Adoption')::int, 4, 'single', 'Which training approach usually helps school staff to adopt new software best?', 'medium', 8, 0, 'Role-based, hands-on training lets each person practise the tasks they will really do.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'One long lecture about every feature of the system, given to all staff together in the school hall.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A long PDF manual sent to each person, who must read it alone before the system goes live next month.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Training only the headmaster, who then teaches everyone else in his own way when he has time.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Short sessions for each role, such as bursar and teachers, with practice on real tasks.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Training and Adoption')::int, 4, 'single', 'Three weeks after training, teachers at a school still record marks on paper. What should you do first?', 'medium', 8, 0, 'Adoption problems have causes. Finding the real barrier lets you fix it instead of repeating what did not work.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the headmaster that the teachers are resisting change and should be ordered to use the system.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Repeat the same full training once more without changing anything, since it worked well at other schools.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the teachers why, for example about skills, devices or time, and then address the barriers.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Close the onboarding project because the training is complete and the school now has the system.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Customer Health Monitoring')::int, 4, 'multiple', 'Which signals may show that a school is at risk of leaving? Select all that apply.', 'medium', 8, 0, 'Low usage, silence and the loss of a champion are warning signs. Asking for training and using reports are healthy signs.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The main users have not logged in for several weeks.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The school asks for training for newly employed staff.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The school does not reply to your messages about the renewal.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The school uses reports from the system every month.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The bursar who championed the system left and nobody replaced them.', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Customer Health Monitoring')::int, 4, 'single', 'What is a customer health score?', 'hard', 10, 0, 'A health score combines several signals so that the team can spot at-risk and healthy accounts early. One number alone, such as payments or tickets, is not enough.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A combined score of usage, support and relationship signals showing how likely the customer is to stay.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The total amount of money that the customer has paid so far, including setup fees and every renewal payment.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The average rating that a customer gives after each support call, on a scale of one to five stars, over a year.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The number of support tickets the customer has opened during the current subscription year.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Retention and Churn Prevention')::int, 4, 'single', 'A school''s logins fell sharply this term and its renewal is in two months. What is the best action?', 'hard', 10, 0, 'Early contact, finding the cause and involving the decision-maker gives the best chance to recover the account.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until the renewal date is very close and then ask the owner whether the school wants to continue.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Offer a large discount immediately, before you have found out why the school''s usage has dropped.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Send a general SMS about the renewal deadline to all customers and wait for this school to reply.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Contact the school now, find the cause, agree a recovery plan, and involve the decision-maker.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Retention and Churn Prevention')::int, 4, 'single', 'What does ''churn'' mean in customer success?', 'easy', 6, 0, 'Churn is the loss of customers, either when they cancel or when they stop paying or using the service.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'New customers who sign up during a month.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Customers who stop using or paying for your service.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Customers who ask for extra training.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Staff who leave your own company.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Retention and Churn Prevention')::int, 4, 'single', 'A school says it will not renew because the fee is too high and it hardly uses the SMS module. What is the best response?', 'hard', 10, 0, 'Understanding actual use and needs lets you offer real value or a better-fitting plan, while respecting the customer''s choice.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Agree and cancel the account at once, without asking any questions about the school''s usage or needs.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Explain that all schools pay the same price, so the fee cannot be discussed or changed for this school.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Review what the school uses, show missing value or suggest a fitting plan, and respect its decision.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the school that the SMS module is compulsory for everyone and cannot be removed from any plan.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Stakeholder Communication')::int, 4, 'single', 'What should a good progress update to a school during onboarding include?', 'easy', 6, 0, 'Clear updates show progress, next steps and shared responsibilities. Hiding problems or giving irrelevant details does not help.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'What is done, what comes next, and what the school must do.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only good news, so that the school stays happy.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Technical details about our servers and databases.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A list of staff members who did not complete training.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Stakeholder Communication')::int, 4, 'single', 'A headmaster complains that parents cannot see fee balances in the app. You find that the school has not yet entered the invoices. How do you respond?', 'medium', 8, 0, 'Honest, polite explanation with clear steps solves the problem and teaches the school. Blaming or making false promises damages trust.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the headmaster that it is a system fault and promise a fix tomorrow.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Explain politely what is missing, show the steps to add the invoices, and offer to help.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Say it is the school''s fault and end the conversation.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Enter the invoices yourself without telling the school.', 0, 0, '', 0, 4);
