  INSERT INTO academy.assessments (skill_id, skill_level_id, title, description, duration_minutes, pass_score, critical_min, total_questions, max_attempts, cooldown_days, version, status, created_at, updated_at) VALUES (v_skill, 4, 'Report Writing — Professional', 'Checks whether the candidate can structure workplace reports, write summaries, use accurate evidence, make recommendations and record minutes.', 30, 70, 60, 12, 1, 7, 1, 'published', now(), now()) RETURNING id INTO v_assess;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Knowledge', 'knowledge', 7, 1) RETURNING id INTO v_sec_k;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Situational Judgment', 'situational', 5, 2) RETURNING id INTO v_sec_s;
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Report Structure and Format')::int, 4, 'single', 'Which order is commonly used for a workplace report?', 'easy', 6, 0, 'A logical flow from purpose to findings to conclusions and recommendations helps the reader to follow the argument.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Recommendations, title, conclusion, introduction, and then the findings at the very end.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Findings, references, title, introduction, and then conclusions in the last section.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Conclusions, appendix, title, findings, and then the introduction after the findings.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Title, introduction or purpose, findings, conclusions, recommendations.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Executive Summary and Clarity')::int, 4, 'single', 'What is an executive summary?', 'easy', 6, 0, 'An executive summary lets a busy reader understand the key points and decisions needed without reading the full report.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A short opening section giving the main findings and recommendations for busy readers.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A list of all the books, articles and websites that the writer used while preparing the report.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The longest section of the report, which contains every data table and chart in full detail.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A copy of the meeting agenda that is attached to the front of the report.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Executive Summary and Clarity')::int, 4, 'single', 'Which content is best for an executive summary?', 'medium', 8, 0, 'A good summary is short and covers purpose, findings and recommendations. Raw data and new information belong elsewhere.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Detailed raw data tables from all twelve months, so that readers can check every single figure.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Long acknowledgements and the history of the organisation, starting from its founding year.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The purpose, key findings and main recommendations, in about one page or less.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'New information that does not appear anywhere else in the report, to surprise the reader.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Executive Summary and Clarity')::int, 4, 'single', 'The school owner has only five minutes to read your 20-page report on fee collection. What do you do?', 'medium', 8, 0, 'A short summary at the front respects the reader''s time and highlights what matters most.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the owner to find more time and read all 20 pages, because every detail matters.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Remove all figures and tables so that the report looks shorter and is easier to read quickly.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Send only the appendix, because it contains all the data that the owner needs to see.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Add a one-page summary at the front with key figures and recommended actions.', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Evidence and Accuracy')::int, 4, 'single', 'Why should a report state the source of its data?', 'medium', 8, 0, 'Stating sources makes the report credible and lets others verify the facts.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that readers can check the information and trust it.', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the report looks longer and more serious.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the writer can avoid being asked questions.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the report can be printed on more pages.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Evidence and Accuracy')::int, 4, 'single', 'While writing a report on attendance, you find that two registers give different totals for the same class. What should you do?', 'hard', 10, 0, 'Accuracy and honesty require checking the source and being open about any doubt. Hiding or guessing damages trust in the report.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use the higher number because it looks better for the school and nobody will ask for proof.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Take the average of the two numbers and use it without telling anyone how you got it.', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Check the original records, find the correct figure, and note any uncertainty.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Leave that class out of the report without explanation, since the totals do not agree.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Evidence and Accuracy')::int, 4, 'multiple', 'Which practices make the findings of a report more reliable? Select all that apply.', 'hard', 10, 0, 'Separating facts from opinion, checking figures and naming sources make a report reliable. Selective data and biased rounding mislead readers.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Separating facts from opinions.', 1, 0, '', 0, 1);
