  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Resource Allocation and Action Planning')::int, 4, 'single', 'Why should the budget be linked to the strategic priorities?', 'hard', 10, 0, 'Resources are limited, so they should support the most important goals.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that every department receives exactly the same amount, whatever its role in the plan.', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that limited money and staff time go to the activities that best support goals.', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the budget never has to change during the year, even if the situation changes.', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that spending on every plan activity needs no approval from the head or the board.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Resource Allocation and Action Planning')::int, 4, 'single', 'Your school can afford only one of three projects: a computer lab, a new library roof, or a school bus. How should you decide?', 'hard', 10, 0, 'Prioritising with clear criteria linked to the strategy leads to fair, defensible decisions.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Divide the money equally among the three projects.', 0, 0, '', 0, 1);
