  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'To check progress, learn from results, and adjust to changes.', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'To find staff to blame.', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Monitoring and Review')::int, 4, 'single', 'At the mid-year review, most targets are behind because the plan assumed a grant that was never received. What should you do?', 'hard', 10, 0, 'A plan must be adjusted when a key assumption fails. Honest review and communication keep the plan realistic.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Continue unchanged and hope that the grant arrives.', 0, 0, '', 0, 1);
