  INSERT INTO academy.assessments (skill_id, skill_level_id, title, description, duration_minutes, pass_score, critical_min, total_questions, max_attempts, cooldown_days, version, status, created_at, updated_at) VALUES (v_skill, 4, 'Child Protection & Safeguarding — Professional', 'Checks whether a candidate can recognise signs of abuse, respond correctly to a disclosure, report and record concerns, keep safe boundaries and protect confidentiality.', 30, 70, 60, 12, 1, 7, 1, 'published', now(), now()) RETURNING id INTO v_assess;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Knowledge', 'knowledge', 7, 1) RETURNING id INTO v_sec_k;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Situational Judgment', 'situational', 5, 2) RETURNING id INTO v_sec_s;
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Recognising Signs of Abuse')::int, 4, 'single', 'Which of these is a possible warning sign that a child is being abused?', 'easy', 6, 0, 'Sudden, unexplained changes in behaviour, mood or attendance are common warning signs. One sign is not proof, but it should be taken seriously.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Being late to school once because of heavy rain', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Asking many questions during a science lesson', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A sudden change in behaviour, such as fear of going home', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Losing a pencil case and feeling sad about it', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Recognising Signs of Abuse')::int, 4, 'multiple', 'Which of the following are recognised forms of child abuse? Select all that apply.', 'easy', 6, 0, 'Physical abuse, neglect and emotional abuse (as well as sexual abuse) are the main forms of child abuse. Homework and praise are normal school practice.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Physical abuse, such as hitting or burning a child', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Setting age-appropriate homework for the class', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Neglect, such as repeatedly failing to give food or care', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Praising a pupil in front of the class', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Emotional abuse, such as constant insults or threats', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Responding to Disclosures')::int, 4, 'single', 'A 10-year-old girl tells you privately that an adult relative touches her in ways that scare her. She begs, "Please do not tell anyone." What should you do?', 'medium', 8, 0, 'Never promise secrecy. Listen, reassure the child, explain that you must tell the person who can help, and do not investigate yourself.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Promise to keep it secret so that she continues to trust you and tells you more', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Listen calmly, say you cannot keep this secret, and tell her you will get help', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Visit the relative at his home and ask him to explain his side of the story first', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask her many detailed questions until you are completely sure that it is true', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Responding to Disclosures')::int, 4, 'single', 'A child has just told you about abuse. Which response is most helpful?', 'medium', 8, 0, 'The child needs to feel believed and not blamed. Questioning, blaming or promising to handle it alone can silence the child and delay protection.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '"Are you sure? That sounds very unlikely, so think carefully."', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '"Why did you wait so long to tell anyone about this?"', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '"Do not tell anyone else; I will handle it myself quietly."', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, '"Thank you for telling me. This is not your fault."', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Reporting and Recording')::int, 4, 'single', 'In most schools, who should a staff member first report a child protection concern to?', 'medium', 8, 0, 'Concerns go to the designated safeguarding person (or head teacher where none is named). Telling the suspected person or discussing widely can put the child at risk.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The school''s designated safeguarding or child protection person', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The parents of the child, before anyone else is told', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The person suspected, so that he or she can respond', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Other teachers in the staffroom, for their advice', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Reporting and Recording')::int, 4, 'single', 'You suspect that the head teacher is abusing a pupil. Normally concerns go to the head teacher. What is the best action?', 'hard', 10, 0, 'When the usual reporting person is involved, report to the next level up or to the external child protection authorities. Do not investigate yourself or delay.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Say nothing, because the head teacher has full authority over all school matters', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Question several pupils yourself first so that you can collect strong proof', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Report to the school board or owner, or to the social welfare office or police', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until the end of term to see whether the pupil says more', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Reporting and Recording')::int, 4, 'single', 'How should you record what a child tells you about abuse?', 'easy', 6, 0, 'Records should be prompt, factual and use the child''s own words. Opinions and late notes weaken the record.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Write the child''s own words with the date and time, as facts only', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Write your opinion about whether the child is telling the truth', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Write a short note from memory a few weeks later', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Write nothing, so that the matter stays private', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Safe Behaviour and Boundaries')::int, 4, 'single', 'A teacher gives extra lessons to one pupil after school. Which arrangement is safest?', 'medium', 8, 0, 'Safe practice avoids being alone with a child out of sight. Open, visible settings protect both the child and the teacher.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'In a closed office with the door shut so other pupils do not disturb them', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'At the teacher''s house, where it is quiet and nobody will interrupt', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'In a visible place, or with another adult nearby and the door open', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'In a parked car while waiting for the pupil''s parent to arrive', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Safe Behaviour and Boundaries')::int, 4, 'multiple', 'You notice that a colleague often gives one pupil gifts, phones the pupil at night, and drives the pupil home alone. Which actions are appropriate? Select all that apply.', 'medium', 8, 0, 'These are warning signs of grooming. You should record facts and report promptly, and leave any investigation to the proper authorities.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Write down factually what you have seen and when', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until you have clear proof before telling anyone', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Warn the colleague privately and keep the matter quiet', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Report your concern to the designated safeguarding person', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the pupil''s classmates to find out what is happening', 0, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Safe Recruitment and Confidentiality')::int, 4, 'single', 'Which step is part of safe recruitment of staff who will work with children?', 'medium', 8, 0, 'Safe recruitment means verifying identity, qualifications and references for every person, paid or unpaid, who will have access to children.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Hiring a friend of the head teacher without an interview or reference check', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Checking identity, certificates and references, including work with children', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Skipping checks for volunteers because they are not paid or only come briefly', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Relying only on how confident the candidate looks', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Safe Recruitment and Confidentiality')::int, 4, 'single', 'In the staffroom a colleague asks about a rumour that a pupil was abused. You know the details because you attended the case meeting. What is the best response?', 'hard', 10, 0, 'Child protection information is confidential and shared only with those who need it to protect the child. Gossip can harm the child and the investigation.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Share a little so that the rumour stops spreading', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell everyone in the staffroom so that all staff can watch the pupil closely', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Politely decline, saying details go only to those who need to know', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Post the main facts on the staff WhatsApp group so everyone is informed', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Recognising Signs of Abuse')::int, 4, 'single', 'A Standard 5 pupil, once cheerful, now sleeps in class, looks hungry, wears dirty clothes, and no adult attends meetings. What is the best first step?', 'hard', 10, 0, 'These may be signs of neglect. Teachers should record observations and pass them to the designated person so the family''s needs and the child''s safety can be assessed.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Punish the pupil for sleeping so that it stops', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Do nothing, since poverty and tiredness are not a child protection matter', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Visit the home alone and confront the parents about how they treat the child', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Record what you see and tell the designated safeguarding person', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_products (skill_id, skill_level_id, assessment_id, price, currency, active, created_at) VALUES (v_skill, 4, v_assess, 10000, 'TZS', 1, now());
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Emergency Response and Priorities', 'Makes the scene safe, calls for help and acts in the right order', 25, 1, 1, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 60);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Bleeding, Burns and Injuries', 'Treats bleeding, burns, nosebleeds and suspected fractures correctly', 20, 0, 2, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Choking, Breathing and Seizures', 'Responds correctly to choking, seizures and a child who is not breathing', 25, 1, 3, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 60);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Illness and Infection Control', 'Uses good hygiene and handles common illnesses such as fever sensibly', 15, 0, 4, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Referral and Record Keeping', 'Knows when to refer to a health facility and records incidents properly', 15, 0, 5, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.assessments (skill_id, skill_level_id, title, description, duration_minutes, pass_score, critical_min, total_questions, max_attempts, cooldown_days, version, status, created_at, updated_at) VALUES (v_skill, 4, 'First Aid & School Health — Professional', 'Checks basic first aid knowledge for common school emergencies, hygiene and infection control, knowing when to refer, and keeping incident records.', 30, 70, 60, 12, 1, 7, 1, 'published', now(), now()) RETURNING id INTO v_assess;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Knowledge', 'knowledge', 6, 1) RETURNING id INTO v_sec_k;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Situational Judgment', 'situational', 6, 2) RETURNING id INTO v_sec_s;
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Emergency Response and Priorities')::int, 4, 'single', 'You arrive at the scene of an accident at school. What should you do first?', 'easy', 6, 0, 'Check for danger first. If you become a casualty yourself, you cannot help anyone.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Move the injured pupil immediately', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give the pupil something to drink', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Start bandaging the most visible injury', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Check that the area is safe for you and the pupil', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Bleeding, Burns and Injuries')::int, 4, 'single', 'A pupil has a nosebleed. What is the correct way to help?', 'easy', 6, 0, 'Leaning forward stops blood running down the throat, and firm pressure on the soft part of the nose usually stops the bleeding.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Sit forward and pinch the soft part of the nose for about 10 minutes', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Lay the pupil flat on the back and tilt the head back so the blood stops running', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Push tissue paper deep into the nostril', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask the pupil to keep blowing the nose hard to clear out the blood', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Bleeding, Burns and Injuries')::int, 4, 'single', 'A pupil cuts her leg deeply on a metal sheet and blood is flowing heavily. What is the best immediate action?', 'medium', 8, 0, 'Direct pressure with a clean cloth is the first treatment for heavy bleeding. Keep pressing, and add more cloth rather than removing a soaked one.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wash the wound with soap and water for 10 minutes before doing anything else', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Press firmly on the wound with a clean cloth and keep pressing until help comes', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tie a tight string or wire above the wound and leave it there until the doctor comes', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Leave the wound open so that it can clot by itself', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Bleeding, Burns and Injuries')::int, 4, 'single', 'A pupil is scalded by hot porridge on the arm. What is the best first aid?', 'medium', 8, 0, 'Cooling with running water reduces damage and pain. Butter, oil and toothpaste can trap heat and cause infection, and blisters should be left intact.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cool the burn under running cool water for at least 10 minutes', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Rub butter or cooking oil on the burn to seal it and keep the air out', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Burst any blisters to let the fluid out and help the skin heal', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cover it with toothpaste to cool it and stop the pain', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Choking, Breathing and Seizures')::int, 4, 'single', 'A child is choking and cannot cough, speak or breathe. What should you do?', 'medium', 8, 0, 'For severe choking, alternate back blows and abdominal thrusts for a child, and get help. Drinks and waiting do not clear a blocked airway.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give water so the food is washed down, then ask the child to lie flat', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Hold the child upside down by the ankles and shake until it drops out', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give 5 back blows, then 5 abdominal thrusts, and call for help', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait and watch to see whether it clears on its own before doing anything', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Choking, Breathing and Seizures')::int, 4, 'multiple', 'A pupil has a convulsive seizure in class. Which actions are correct? Select all that apply.', 'hard', 10, 0, 'Protect the head, never restrain or put anything in the mouth, time the seizure, and keep checking breathing afterwards. Call emergency help if it lasts too long or repeats.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Move hard objects away and cushion the head', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Hold the pupil down firmly to stop the movements', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Put a spoon or stick in the mouth to protect the tongue', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Note the time, and place the pupil in the recovery position when the jerking stops', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Get an adult to stay with the pupil and check breathing until fully awake', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Emergency Response and Priorities')::int, 4, 'single', 'A pupil collapses on the field, does not respond and is not breathing normally. What is the best action?', 'hard', 10, 0, 'A person who is unresponsive and not breathing normally needs urgent help and CPR. Delay or moving the person wastes vital time.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Carry the pupil to the staff room, lay him on a bench, and wait quietly for him to wake up', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Splash water on the face and wait a few minutes to see whether he wakes up', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give a sweet drink to restore energy', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Shout for help, call emergency services, and start chest compressions if trained', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Illness and Infection Control')::int, 4, 'single', 'When should a first aider wash their hands?', 'easy', 6, 0, 'Handwashing with soap before and after treatment protects both the helper and the pupil from infection.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Before and after treating a pupil, using soap and clean water', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only at the end of the day', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only if the hands look very dirty', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only after treating a pupil with blood on the skin', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Illness and Infection Control')::int, 4, 'single', 'A pupil has a high fever, chills, headache and has vomited, in an area where malaria is common. What is the best action?', 'medium', 8, 0, 'Fever in a child may be malaria and needs prompt testing and treatment. Do not give unprescribed medicine or delay.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Send the pupil back to class after a cold drink and a short rest outside in the shade', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give leftover antibiotics from the staff room cupboard and watch the pupil', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Keep the pupil resting, inform the parents, and refer to a clinic for testing', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wait until the next day to see if the fever goes away by itself, and only then decide', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Referral and Record Keeping')::int, 4, 'single', 'Which details should be written in a school incident or first aid record?', 'medium', 8, 0, 'A good record is factual: when and what happened, the care given and who was told. Opinions and photos shared on groups break confidentiality.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only the name of the pupil', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Date, time, what happened, treatment given, and who was informed', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Your opinion about who is to blame', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A photo of the pupil to share on the class group', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Referral and Record Keeping')::int, 4, 'single', 'During football a pupil hits his head. An hour later he vomits and seems very sleepy. What should you do?', 'hard', 10, 0, 'Vomiting and drowsiness after a head injury can mean serious injury to the head. The pupil needs urgent medical assessment, and parents must be told.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Let him rest in class and check again tomorrow', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give him tea and send him back to the field', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Arrange urgent medical care and inform his parents', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell him to sleep at the sick bay and not disturb him', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Bleeding, Burns and Injuries')::int, 4, 'single', 'A pupil falls from a tree and cannot move his arm, which looks bent and is painful. What is the best first aid?', 'medium', 8, 0, 'A suspected fracture should be supported and kept still, not straightened or moved, and the pupil taken to a health facility.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Pull the arm straight to see whether it moves normally and how much it hurts', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Rub oil on the arm and massage it gently to ease the pain', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Ask him to move the arm to test it', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Keep the arm still and supported as found, then take him for medical care', 1, 0, '', 0, 4);
