  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.skill_competencies (skill_id, name, description, weight, is_critical, sort_order, status) VALUES (v_skill, 'Kitchen Safety and Cleaning', 'Works safely in the kitchen and cleans correctly', 20, 0, 5, 1) RETURNING id INTO v_c;
  INSERT INTO academy.skill_competency_levels (competency_id, skill_level_id, description, minimum_score) VALUES (v_c, 4, 'Professional minimum standard', 50);
  INSERT INTO academy.assessments (skill_id, skill_level_id, title, description, duration_minutes, pass_score, critical_min, total_questions, max_attempts, cooldown_days, version, status, created_at, updated_at) VALUES (v_skill, 4, 'Food Safety & Catering — Professional', 'Checks school kitchen staff knowledge of hygiene, preventing cross-contamination, temperature control and storage, menu planning and kitchen safety.', 30, 70, 60, 12, 1, 7, 1, 'published', now(), now()) RETURNING id INTO v_assess;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Knowledge', 'knowledge', 6, 1) RETURNING id INTO v_sec_k;
  INSERT INTO academy.assessment_sections (assessment_id, name, type, num_questions, sort_order) VALUES (v_assess, 'Situational Judgment', 'situational', 6, 2) RETURNING id INTO v_sec_s;
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Personal Hygiene')::int, 4, 'single', 'When must kitchen staff wash their hands with soap and water?', 'easy', 6, 0, 'Hands carry germs that cannot be seen. Wash after the toilet, after raw meat, waste or eating, and before food preparation.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only at the end of the working day, when the kitchen is closed and cleaned', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only when the hands look visibly dirty or sticky after working', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'After using the toilet and after handling raw meat or fish', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Only after eating a meal or drinking tea during the break', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Personal Hygiene')::int, 4, 'single', 'A cook has diarrhoea and vomiting this morning but says he can work because the kitchen is short of staff. What is correct?', 'medium', 8, 0, 'People with diarrhoea or vomiting can spread illness through food. They must stay away from food work until well and cleared.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'He may continue cooking if he wears gloves and a mask the whole time', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'He may work only on the cold dishes, away from the hot cooking area', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'He should stay off food handling until he is well and cleared', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'He may work if he washes his hands more often during the shift', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Cross-Contamination and Safe Handling')::int, 4, 'single', 'Why should raw meat and ready-to-eat food use separate boards and knives?', 'easy', 6, 0, 'Raw foods carry bacteria. Using separate equipment stops these spreading to food eaten without further cooking.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the knives stay sharp longer', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that bacteria from raw food do not pass to food that will not be cooked again', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the food keeps its flavour', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'So that the boards can be washed less often', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Cross-Contamination and Safe Handling')::int, 4, 'single', 'You have just cut raw chicken and now must slice tomatoes for the salad. What should you do?', 'medium', 8, 0, 'Salad is not cooked, so any chicken bacteria left on equipment will reach the pupils. Clean thoroughly or use separate equipment.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wipe the knife and board with a dry cloth, then carry on slicing the tomatoes', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wash your hands, then use a clean board and knife, or wash and sanitise them', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Rinse the board with cold water only and carry on with the same knife', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Slice the tomatoes on the same board without cleaning it, since they will be washed later', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Temperature Control and Storage')::int, 4, 'single', 'What does the "danger zone" for food mean?', 'medium', 8, 0, 'Bacteria grow quickly between roughly 5 and 60 degrees Celsius. Food should be kept cold or served hot, and not left in this range.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The range between about 5 degrees and 60 degrees Celsius, where bacteria multiply fastest', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Temperatures above 100 degrees Celsius', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Temperatures below freezing', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Any food stored near the cooker', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Temperature Control and Storage')::int, 4, 'multiple', 'Rice and beans were cooked for lunch and some is left over. Which practices are safe? Select all that apply.', 'hard', 10, 0, 'Leftovers must be cooled and chilled promptly and reheated until very hot. Food left too long in the danger zone should be thrown away.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Cool it quickly in shallow containers and refrigerate within about two hours', 1, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Leave the pot covered on the stove overnight', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Reheat it until steaming hot all the way through', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Mix the leftover into a fresh batch so it is not wasted', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Throw away food that has stood at room temperature for many hours', 1, 0, '', 0, 5);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Temperature Control and Storage')::int, 4, 'single', 'What does "first in, first out" (FIFO) mean in a food store?', 'easy', 6, 0, 'FIFO rotates stock so older items are used before they spoil or expire.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use the newest stock first', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use the cheapest stock first', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use the heaviest sacks first', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Use the oldest stock first', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Temperature Control and Storage')::int, 4, 'single', 'Where should sacks of maize flour and beans be stored?', 'medium', 8, 0, 'Dry foods need to be kept off the floor, dry and protected from pests and chemicals to avoid spoilage and contamination.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Directly on the floor, against the wall, to save space on the shelves', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'On racks off the floor, in a dry, ventilated, pest-proof store', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'In the open yard under a sheet, so that the store stays free', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Next to the cleaning chemicals to save space in the small store room', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Menu Planning and Portions')::int, 4, 'single', 'You plan weekly meals for 300 boarders on a limited budget. Which menu approach is best?', 'medium', 8, 0, 'A balanced school menu combines staple foods, protein, and vegetables or fruit, with variety, and can still be affordable.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'The cheapest staple only, every day, to save money', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Rice and meat every day, because pupils like it', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Whatever the pupils ask for on each day', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'A staple with beans, fish or eggs, plus vegetables, with variety through the week', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Menu Planning and Portions')::int, 4, 'single', 'The parent of a pupil has told the school that the pupil is allergic to groundnuts, and today''s sauce contains groundnuts. What should you do?', 'hard', 10, 0, 'Allergens can cause serious reactions even in small amounts. Prepare a separate safe meal and avoid cross-contact.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Remove the groundnuts from the pupil''s plate only and serve it from the same pot', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Tell the pupil to eat a small amount to see whether any reaction happens', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Give the pupil the same food and watch carefully for any signs of a reaction', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Prepare a separate safe meal with clean utensils and tell the serving staff', 1, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Kitchen Safety and Cleaning')::int, 4, 'single', 'Cooking oil in a pan catches fire. What should you do?', 'hard', 10, 0, 'Water makes oil fires spread violently. Switch off the heat if safe and smother the flames by cutting off air.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Pour a full bucket of water onto the burning pan to put the fire out quickly', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Turn off the heat if safe, and cover the pan with a lid or damp cloth', 1, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Carry the pan outside quickly while the oil is still burning', 0, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Fan the flames to blow the fire out before it spreads further', 0, 0, '', 0, 4);
  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Kitchen Safety and Cleaning')::int, 4, 'single', 'How should kitchen work surfaces be cleaned?', 'medium', 8, 0, 'Cleaning removes dirt and grease, and sanitising then reduces germs. Sanitiser does not work well on dirty surfaces.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wipe with a damp cloth only, then leave the surface to dry in the air', 0, 0, '', 0, 1);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Spray with air freshener so that the surface smells clean and fresh', 0, 0, '', 0, 2);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Clean with detergent and water first, then sanitise', 1, 0, '', 0, 3);
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Sweep with a dry broom and then leave it until the next day', 0, 0, '', 0, 4);
