  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_s, v_skill, (v_comp->>'Hazard Identification and Control')::int, 4, 'single', 'You see exposed electrical wires hanging in a corridor used by pupils. What is the best action?', 'medium', 8, 0, 'Exposed live wires can kill. Make the area safe immediately and use a qualified person for the repair.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Wrap the wires with insulating tape yourself and leave them where they are', 0, 0, '', 0, 1);
