  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Hazard Identification and Control')::int, 4, 'single', 'A corridor has just been mopped and is wet. What should you do?', 'easy', 6, 0, 'A warning sign reduces slips and falls while the floor is wet.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Put up a "wet floor" sign until it is dry', 1, 0, '', 0, 1);
