  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Fire Safety')::int, 4, 'single', 'Which three things does a fire need to burn?', 'easy', 6, 0, 'Fire needs heat, fuel and oxygen. Removing any one of them puts the fire out.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'Heat, smoke and running water', 0, 0, '', 0, 1);
