  INSERT INTO academy.assessment_questions (assessment_id, section_id, skill_id, competency_id, skill_level_id, question_type, question_text, difficulty, points, time_seconds, explanation, ai_generated, status, is_active, created_at, updated_at) VALUES (v_assess, v_sec_k, v_skill, (v_comp->>'Contractor and Repair Management')::int, 4, 'single', 'Before hiring a contractor for electrical work, what should you check?', 'medium', 8, 0, 'Verify competence and agree a written scope and price. Poor electrical work is a serious safety risk.', 1, 'published', 1, now(), now()) RETURNING id INTO v_q;
  INSERT INTO academy.assessment_question_options (question_id, option_text, is_correct, score, match_key, correct_order, sort_order) VALUES (v_q, 'That the contractor is a relative of a staff member who recommended him', 0, 0, '', 0, 1);
